import {
    Table,
    StringColumn,
    ListColumn,
    BooleanColumn,
    IntegerColumn,
    TranslatedTextColumn,
    ReferenceColumn,
    GenericColumn,
    GuidColumn,
} from '@servicenow/sdk/core'

export const sys_hub_flow_base = Table({
    allowWebServiceAccess: true,
    extends: 'sys_hub_flow_block',
    extensible: true,
    label: 'Flow Base',
    name: 'sys_hub_flow_base',
    schema: {
        internal_name: StringColumn({
            label: 'Internal name',
            maxLength: 255,
        }),
        run_with_roles: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: 'Run flow with roles',
            maxLength: 1024,
            readOnly: true,
            readOnlyOption: 'instance_configured',
            referenceTable: 'sys_user_role',
        }),
        callable_by_client_api: BooleanColumn({
            default: false,
            label: 'Callable by Client API',
        }),
        acls: ListColumn({
            attributes: {
                no_sort: true,
                slushbucket_ref_no_expand: true,
            },
            label: 'ACLs',
            maxLength: 1024,
            referenceTable: 'sys_security_acl',
            referenceQual: 'type=client_callable_flow_object',
        }),
        attributes: StringColumn({
            label: 'Attributes',
            maxLength: 4000,
        }),
        flow_priority: StringColumn({
            dropdown: 'dropdown_with_none',
            label: 'Flow Priority',
        }),
        authored_on_release_version: IntegerColumn({
            label: 'Authored on release version',
        }),
        version: StringColumn({
            default: '1',
            label: 'Version',
        }),
        description: StringColumn({
            label: 'Description',
            maxLength: 4000,
        }),
        active: BooleanColumn({
            default: true,
            label: 'Active',
            mandatory: true,
        }),
        annotation: TranslatedTextColumn({
            attributes: {
                serializer: 'com.glide.script.TranslatedTextXMLSerializer',
            },
            label: 'Annotation',
            maxLength: 250,
        }),
        natlang: StringColumn({
            label: 'Natural Language Title',
            maxLength: 4000,
        }),
        category: ReferenceColumn({
            attributes: {
                encode_utf8: false,
            },
            label: 'Category',
            referenceTable: 'sys_hub_category',
        }),
        outputs: GenericColumn({
            attributes: {
                list_layout_ignore: true,
                model_field: 'sys_id',
                record_watcher_blacklist: true,
                serializer: 'com.glide.vars.VariableValueXMLSerializer',
                slushbucket_ref_no_expand: true,
            },
            columnType: 'glide_var',
            label: 'Outputs',
            maxLength: 32,
            referenceTable: 'sys_hub_flow_output',
        }),
        remote_trigger_id: StringColumn({
            label: 'Remote trigger ID',
            maxLength: 32,
        }),
        sc_callable: BooleanColumn({
            default: false,
            label: 'Sc callable',
        }),
        copied_from: StringColumn({
            label: 'Copied from',
            maxLength: 32,
        }),
        copied_from_name: StringColumn({
            label: 'Copied from name',
            maxLength: 32,
        }),
        run_as: StringColumn({
            default: 'user',
            dropdown: 'dropdown_with_none',
            label: 'Run As',
        }),
        status: StringColumn({
            default: 'draft',
            dropdown: 'dropdown_with_none',
            label: 'Status',
            mandatory: true,
        }),
        type: StringColumn({
            default: 'flow',
            dropdown: 'dropdown_with_none',
            label: 'Flow Type',
            mandatory: true,
        }),
        access: StringColumn({
            default: 'public',
            dropdown: 'dropdown_with_none',
            label: 'Accessible From',
            mandatory: true,
        }),
        sys_id: GuidColumn({
            label: [
                {
                    label: 'Sys ID',
                    plural: 'Sys IDs',
                    language: 'en',
                },
            ],
            primary: true,
        }),
    },
})
